<script lang="ts">import { onMount } from 'svelte'; import { api } from '$lib/api'; type Branch={id:string;name:string}; type Summary={branchId:string;interfaces?:number;activeConnections?:number;ipObservations?:number}; let branches:Branch[]=[];let branchId='';let summary:Summary|null=null;let loading=true;let error='';async function load(){loading=true;error='';try{const b=await api.get<{items?:Branch[]}|Branch[]>('/api/branches');branches=Array.isArray(b)?b:b.items??[];branchId ||= branches[0]?.id??'';if(branchId) summary=await api.get<Summary>(`/api/branches/${branchId}/connectivity`)}catch(e){error=(e as Error).message}finally{loading=false}}onMount(load);async function change(){summary=null;await load()}</script>
<svelte:head><title>Connectivity — Oracle Inventory</title></svelte:head><div class="page"><h1>Branch connectivity</h1><p>Restricted network summary. Detailed IP/VLAN/topology fields require sensitive-network permission.</p>{#if loading}<section class="panel" role="status">Loading connectivity…</section>{:else if error}<section class="panel" role="alert">{error}<button onclick={load}>Retry</button></section>{:else}<section class="panel"><label for="branch">Authorized branch</label><select id="branch" bind:value={branchId} onchange={change}>{#each branches as branch}<option value={branch.id}>{branch.name}</option>{/each}</select>{#if !summary}<p>No connectivity summary is available for this branch.</p>{:else}<dl><div><dt>Interfaces</dt><dd>{summary.interfaces ?? '—'}</dd></div><div><dt>Active connections</dt><dd>{summary.activeConnections ?? '—'}</dd></div><div><dt>IP observations</dt><dd>{summary.ipObservations ?? '—'}</dd></div></dl>{/if}</section>{/if}</div><style>.page{max-width:900px;margin:auto;padding:32px}.panel{border:1px solid #ddd;border-radius:10px;padding:20px;margin-top:16px}label{display:block;font-weight:600}select{padding:8px;margin:8px 0;width:100%}dl{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}dt{font-weight:600}dd{margin:4px 0 0}</style>
